import {result,operation,symbol} from './math-games.js';
export const PLACES=['ones','tens','hundreds'];
const digits=n=>[n%10,Math.floor(n/10)%10,Math.floor(n/100)%10];
export class ColumnLesson{
 constructor(fact){this.fact=fact;this.top=digits(fact.a);this.bottom=digits(fact.b);this.width=Math.max(String(fact.a).length,String(fact.b).length,String(result(fact)).length);this.column=0;this.carry=0;this.answers=[];this.carries=[];this.mistakes=0;this.trades=0;this.message='Start in the ones column.';}
 get complete(){return this.column>=this.width;}
 get needsTrade(){return operation(this.fact)==='subtract'&&this.top[this.column]<this.bottom[this.column];}
 get total(){return operation(this.fact)==='add'?this.top[this.column]+this.bottom[this.column]+this.carry:this.top[this.column]-this.bottom[this.column];}
 trade(index){if(this.complete||!this.needsTrade||index<=this.column||index>=this.width||this.top[index]===0||(index>this.column+1&&this.top[index-1]>0)){this.message='Trade from the nearest column on the left that has something to share.';return false;}this.top[index]--;this.top[index-1]+=10;this.trades++;this.message=`Traded 1 ${PLACES[index].slice(0,-1)} for 10 ${PLACES[index-1]}. The total value stayed the same.`;return true;}
 submit(raw,carryRaw='0'){
  if(this.complete)return false;if(this.needsTrade){this.message='Not enough in this column yet. Tap a digit on the left to regroup.';return false;}
  const expected=this.total,outgoing=operation(this.fact)==='add'?Math.floor(expected/10):0;
  if(!/^\d$/.test(String(raw).trim())||+raw!==expected%10||!/^\d$/.test(String(carryRaw).trim())||+carryRaw!==outgoing){this.mistakes++;this.message=operation(this.fact)==='add'?`${this.top[this.column]} + ${this.bottom[this.column]}${this.carry?' + '+this.carry+' carried':''} = ${expected}. Write ${expected%10}${outgoing?' and carry '+outgoing:' in this column'}.`:`${this.top[this.column]} − ${this.bottom[this.column]} = ${expected}. Try that column again.`;return false;}
  this.answers[this.column]=+raw;this.carries[this.column+1]=outgoing;this.carry=outgoing;this.column++;this.message=this.complete?'You built the whole answer!':`Nice! Move left to the ${PLACES[this.column]} column.`;return true;
 }
}
export class BlockLesson{
 constructor(fact){this.fact=fact;this.counts=digits(fact.a);this.remaining=operation(fact)==='subtract'?digits(fact.b):[0,0,0];if(operation(fact)==='add'){const b=digits(fact.b);this.counts=this.counts.map((n,i)=>n+b[i]);}this.mistakes=0;this.trades=0;this.message=operation(fact)==='add'?'Combine the blocks. Trade every group of ten for one bigger block.':'Take away the second number. Tap blocks to remove them; trade a bigger block when you need more.';}
 get complete(){return this.remaining.every(n=>n===0)&&this.counts.every(n=>n<10)&&this.counts.reduce((n,v,i)=>n+v*10**i,0)===result(this.fact);}
 canTrade(index){return operation(this.fact)==='add'?index>=0&&index<2&&this.counts[index]>=10:index>=1&&index<=2&&this.counts[index]>0&&this.remaining.slice(0,index).some((n,i)=>n>this.counts[i])&&!(index===2&&this.counts[1]>0&&this.remaining[1]<=this.counts[1]);}
 trade(index){if(!this.canTrade(index)){this.message='Trade only when you need more smaller blocks, or when ten blocks can become one bigger block.';return false;}if(operation(this.fact)==='add'){if(index<0||index>1||this.counts[index]<10)return false;this.counts[index]-=10;this.counts[index+1]++;this.message=`10 ${PLACES[index]} became 1 ${PLACES[index+1].slice(0,-1)}. Same value, fewer blocks!`;}else{if(index<1||index>2||!this.counts[index]||!this.remaining.slice(0,index).some((n,i)=>n>this.counts[i])||(index===2&&this.counts[1]>0&&this.remaining[1]<=this.counts[1]))return false;this.counts[index]--;this.counts[index-1]+=10;this.message=`1 ${PLACES[index].slice(0,-1)} became 10 ${PLACES[index-1]}. Now you can take away more.`;}this.trades++;return true;}
 remove(index){if(!this.remaining[index]||!this.counts[index])return false;this.counts[index]--;this.remaining[index]--;this.message=this.complete?'Your blocks show the answer. Check your work!':`Removed 1 ${PLACES[index].slice(0,-1)}. Keep going.`;return true;}
 check(){if(this.complete)return true;this.mistakes++;this.message=this.remaining.some(n=>n>0)?'There are still blocks to take away. Trade a bigger block if you need more.':'Trade groups of ten until every column has fewer than ten blocks.';return false;}
}
export function workshopView(lesson,format){const f=lesson.fact;if(format==='columns')return `<section class="workshop"><h2>Build it one column at a time</h2><p>Work from right to left. ${operation(f)==='subtract'?'Tap a top digit to trade with the column beside it.':'Write the digit below and put any carried 1 in its own box.'}</p><table class="interactive-columns"><thead><tr><th></th>${PLACES.slice(0,lesson.width).reverse().map(p=>`<th>${p}</th>`).join('')}</tr></thead><tbody><tr class="carry-row"><th>carry</th>${Array.from({length:lesson.width},(_,j)=>lesson.width-1-j).map(i=>`<td>${lesson.carries[i]||''}</td>`).join('')}</tr><tr><th></th>${Array.from({length:lesson.width},(_,j)=>lesson.width-1-j).map(i=>`<td class="${i===lesson.column?'current-column':''}">${operation(f)==='subtract'&&i>lesson.column?`<button data-action="column-trade:${i}" aria-label="Trade one ${PLACES[i].slice(0,-1)} for ten ${PLACES[i-1]}">${lesson.top[i]}</button>`:lesson.top[i]}</td>`).join('')}</tr><tr><th>${symbol(f)}</th>${lesson.bottom.slice(0,lesson.width).reverse().map(n=>`<td>${n}</td>`).join('')}</tr><tr class="column-result"><th>=</th>${Array.from({length:lesson.width},(_,j)=>lesson.width-1-j).map(i=>`<td>${lesson.answers[i]??'?'}</td>`).join('')}</tr></tbody></table><form id="column-form" class="column-entry"><label>${PLACES[lesson.column]} digit<input id="column-digit" inputmode="numeric" pattern="[0-9]" maxlength="1" autocomplete="off" required></label>${operation(f)==='add'&&lesson.total>=10?'<label>Carry to the left<input id="carry-digit" inputmode="numeric" pattern="[0-9]" maxlength="1" autocomplete="off" required></label>':''}<button class="primary" ${lesson.needsTrade?'disabled':''}>Check column →</button></form><p class="lesson-message" role="status">${lesson.message}</p></section>`;
 return `<section class="workshop"><h2>Build the answer with blocks</h2><p>One square = 1 · one rod = 10 · one flat = 100.</p><div class="block-columns">${[2,1,0].map(i=>`<section><h3>${PLACES[i]}</h3><strong>${lesson.counts[i]} ${PLACES[i]}</strong><div class="blocks">${Array.from({length:lesson.counts[i]},()=>operation(f)==='subtract'?`<button class="block-hit" data-action="block-remove:${i}" ${lesson.remaining[i]?'':'disabled'} aria-label="Remove one ${PLACES[i].slice(0,-1)}"><span class="base-block block-${i}" aria-hidden="true"></span></button>`:`<span class="base-block block-${i}" aria-hidden="true"></span>`).join('')}</div>${operation(f)==='subtract'?`<p>Take away ${lesson.remaining[i]} more</p>${i?`<button class="trade-button" data-action="block-trade:${i}" ${lesson.canTrade(i)?'':'disabled'}>Trade 1 ${PLACES[i].slice(0,-1)} → 10 ${PLACES[i-1]}</button>`:''}`:i<2?`<button class="trade-button" data-action="block-trade:${i}" ${lesson.counts[i]>=10?'':'disabled'}>Trade 10 ${PLACES[i]} → 1 ${PLACES[i+1].slice(0,-1)}</button>`:''}</section>`).join('')}</div><p class="lesson-message" role="status">${lesson.message}</p><button class="primary" data-action="block-check">Check my blocks →</button></section>`;
}
